"""Lock files: one pinned package per line.

    # generated by verspec
    requests == 2.31.0
    left-pad==1.3.0        # pinned for the build
    Flask==3.0.0

Blank lines and `#` comments (whole-line or trailing) are ignored. Package
names are case-insensitive and stored lower-case; spaces around `==` are
allowed. A package may be pinned only once.
"""

import collections

from .version import Version, VersionError


class LockError(ValueError):
    """Raised for a malformed lock file; the message names the line."""


def parse_lock(text):
    """OrderedDict name -> Version, in file order."""
    pins = collections.OrderedDict()
    for line_no, raw in enumerate(text.splitlines(), 1):
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        parts = line.split("==")
        if len(parts) != 2 or not parts[0].strip() or not parts[1].strip():
            raise LockError("line %d: expected 'name==version', got %r" % (line_no, line))
        name = parts[0].strip().lower()
        try:
            version = Version.parse(parts[1].strip())
        except VersionError as exc:
            raise LockError("line %d: %s" % (line_no, exc))
        if name in pins:
            raise LockError("line %d: duplicate package '%s'" % (line_no, name))
        pins[name] = version
    return pins


def dump_lock(pins, header="# generated by verspec"):
    """Lock file text, packages sorted by name, ending with a newline."""
    lines = [header] if header else []
    for name in sorted(pins):
        lines.append("%s==%s" % (name, pins[name]))
    return "\n".join(lines) + "\n"


def diff_locks(old, new):
    """Changes between two parsed lock files.

    Returns a dict with sorted lists: added [(name, version)], removed
    [(name, version)] and changed [(name, old, new)].
    """
    added = [(n, new[n]) for n in sorted(new) if n not in old]
    removed = [(n, old[n]) for n in sorted(old) if n not in new]
    changed = [(n, old[n], new[n]) for n in sorted(old)
               if n in new and str(old[n]) != str(new[n])]
    return {"added": added, "removed": removed, "changed": changed}


def check_lock(pins, constraints):
    """Names whose pinned version violates its constraint.

    `constraints` maps name -> Constraint. Packages without a constraint are
    fine; constrained packages missing from the lock are reported too.
    """
    problems = []
    for name in sorted(constraints):
        if name not in pins:
            problems.append("%s: not pinned" % name)
        elif not constraints[name].matches(pins[name]):
            problems.append("%s: %s does not satisfy %s" % (
                name, pins[name], constraints[name].text))
    return problems
